1	@define-color primary #7fd0ff;
2	@define-color primary-container #004c6a;
3	@define-color outline #919191;
4	
5	* {
6	    font-family: "JetBrainsMono Nerd Font";
7	    font-size: 16px;
8	    background: none;
9	}
